def _envelope_mismatch(block_id: str, data: Dict[str, Any]) -> tuple:
    """Is the caller's record one level too deep for this block?

    Returns ``(buried, colliding)`` -- the keys the block reads that sit
    inside ``data["input"]`` instead of at the top level, and any of those
    that already exist at the top level with a different value.

    THE INCIDENT (residential-lettings, sess_6400b6c273414352, post-#254).
    ``unit_registry_and_vacancy_tracking`` called::

        execute("analytics", {"input": {"metric": "monthly_rent_gbp",
                                        "value": 1450.0, ...}},
                action="track_event")

    and got ``{'error': 'metric and value required'}``. Verified literally in
    the block source: ``AnalyticsBlock._track_event`` reads
    ``data.get("metric")`` and ``data.get("value")`` off the payload it is
    handed, and ``analytics``' block.json declares ``input`` only as a config
    slot -- the code never reads it. Both fields were present in the spec, so
    a plan-time audit that looks for NAMES passes; the block still saw
    neither. That is #254's class one level deeper, and the same file wrapped
    three different shapes with no rule.
    """
    reads = _keys_read(block_id)
    if not reads or "input" in reads:
        # The block genuinely reads an ``input`` key (``workflow`` does).
        # Its wrapper is the contract, not a mistake.
        return (), ()
    inner = data.get("input")
    if not isinstance(inner, dict):
        return (), ()
    buried = sorted(k for k in inner if k in reads and k != "action")
    colliding = sorted(
        k for k in buried if k in data and data[k] != inner[k]
    )
    return tuple(buried), tuple(colliding)


def _adapt_input(block_id: str, payload: Any, action: str | None) -> Dict[str, Any]:
    """Pass the caller payload through. Never invent Store fields (F18).

    A MISMATCHED ENVELOPE IS NEVER PASSED THROUGH SILENTLY. Either the
    record is normalised to the shape the block reads, or the call fails
    with the mismatch named -- it does not reach the block wearing a shape
    the block cannot read (owner's ruling R1d, 2026-09-01).
    """
    data = dict(payload) if isinstance(payload, dict) else {"value": payload}
    known = _known_fields(block_id)

    buried, colliding = _envelope_mismatch(block_id, data)
    if colliding:
        # Two different values for the same field, one nested and one flat.
        # Normalising would have to choose, and choosing is inventing.
        verb = "appears" if len(colliding) == 1 else "appear"
        raise DispatchContractError(
            f"{block_id} envelope mismatch: {', '.join(colliding)} {verb} both "
            f"at the top level and inside 'input' with different values; "
            f"{block_id} reads them at the top level. Pass the record flat."
        )
    if buried:
        inner = dict(data.get("input") or {})
        for key in buried:
            data[key] = inner.pop(key)
        if inner:
            data["input"] = inner
        else:
            data.pop("input", None)
        _LIFTED.append((block_id, tuple(buried)))
    # Store blocks are action-dispatched: the domain record travels in the
    # block's declared ``input`` slot, with block params beside it. A handler
    # that passes the record flat gets every domain key refused as unknown --
    # measured on the warehouse `audit` capability, which declares
    # reference/status/quantity in its own model and had all three rejected.
    #
    # This is adaptation, not F18 fabrication. No value is invented and no
    # field is conjured to satisfy a validator: the caller's own record is
    # placed in the field the block declares for exactly it. If the caller
    # already supplied ``input``, nothing is moved.
    if known and "input" in known and "input" not in data:
        stray = {k: v for k, v in data.items() if k not in known}
        if stray:
            data = {k: v for k, v in data.items() if k in known}
            data["input"] = stray
    missing = [
        field for field in _required_fields(block_id)
        if field not in data or data[field] in (None, "")
    ]
    if missing:
        raise DispatchContractError(
            f"{block_id} missing required field(s): {', '.join(missing)}"
        )
    if known:
        unknown = sorted(str(key) for key in data if key not in known)
        if unknown:
            raise DispatchContractError(
                f"{block_id} unknown field(s): {', '.join(unknown)}"
            )
    return data


#: A block that answers with one of these has NOT succeeded. "partial" is the
#: word both the workflow and notification blocks use for "some of it failed"
#: -- workflow sets it on every step that raises, times out, names an unknown
#: block, or returns an error. Reading only "error" let a pipeline whose only
#: step failed come back as success.
_FAILED_STATUSES = {"error", "failed", "partial"}


def _failed_steps(result: Dict[str, Any]) -> list:
    """Sub-step failures the top-level status may not carry.

    Live, from the booted sess_6400b6c zip: punch_list_tracking returned
    ``ok: true`` wrapped around

        {"status": "partial", "results": [{"step_id": "step_0",
          "block": "database", "status": "failed",
          "error": "DatabaseBlock.__init__() missing 2 required positional
          arguments: 'hal_block' and 'config'"}]}

    The capability reported success. The row was never written.
    """
    steps = result.get("results")
    if not isinstance(steps, list):
        steps = result.get("steps")
    if not isinstance(steps, list):
        return []
    return [
        step for step in steps
        if isinstance(step, dict)
        and str(step.get("status") or "").lower() in {"error", "failed"}
    ]


def _error_envelope(block_id: str, action: str | None, error: str) -> Dict[str, Any]:
    return {
        "status": "error",
        "block": block_id,
        "action": action,
        "error": error,
        "ok": False,
    }


def _force_utf8_stdio() -> None:
    """F13: a checkmark/emoji print must not become a charmap crash.

    Windows cp1252 consoles encode print() with the console codepage. A
    vendored block that prints one checkmark used to raise UnicodeEncodeError;
    execute() then swallowed that into a generic error envelope that looked
    like a domain refusal. Force UTF-8 on this process before the block runs.
    """
    import os
    import sys

    os.environ["PYTHONIOENCODING"] = "utf-8"
    os.environ["PYTHONUTF8"] = "1"
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if not callable(reconfigure):
            continue
        try:
            reconfigure(encoding="utf-8", errors="replace")
        except (OSError, ValueError, AttributeError):
            continue


_force_utf8_stdio()


def execute(
    block_id: str,
    payload: Dict[str, Any],
    action: str | None = None,
    params: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    """Run a vendored block locally and return its result envelope.

    Real Store blocks are action-dispatched: the domain data travels as
    ``input`` and the operation name as ``action`` (each block declares a
    default in its block.json). A call with no action reaches blocks that
    answer "Unknown action" -- pass the one the capability needs.

    Missing required fields and unknown fields/params become an error
    envelope. A block refusal (status=error) is returned as-is — never
    rewritten to ok.
    """
    module = load_block(block_id)
    run = getattr(module, "run", None)
    if run is None:
        raise BlockNotVendored(f"{block_id} exposes no run() entry point")
    contract = BLOCK_CONTRACTS.get(block_id) or {}
    declared = set()
    for item in contract.get("declared_inputs") or []:
        name = item.get("name") if isinstance(item, dict) else None
        if name:
            declared.add(name)
    if (
        params
        and (contract.get("declared_inputs") or contract.get("input_required_fields"))
    ):
        extra = sorted(
            str(key) for key in params if key not in declared and key != "action"
        )
        if extra:
            return _error_envelope(
                block_id, action, f"unknown param(s): {', '.join(extra)}"
            )
    kwargs = dict(params or {})
    if action is not None:
        kwargs["action"] = action
    try:
        adapted = _adapt_input(block_id, payload, action)
    except DispatchContractError as exc:
        return _error_envelope(block_id, action, str(exc))
    # A block-level failure comes back as data, not as an exception. The
    # Store's shim raises RuntimeError on an error envelope, which destroys
    # the diagnosis: a handler (and a failing test) sees "Input validation
    # failed" with no block name and no field list. Structural failures --
    # a block that is not vendored -- still raise above.
    _force_utf8_stdio()
    try:
        result = run(input=adapted, **kwargs)
    except BlockNotVendored:
        raise
    except UnicodeEncodeError as exc:
        return _error_envelope(
            block_id,
            action,
            f"UnicodeEncodeError on block stdout (encoding, not domain): {exc}",
        )
    except Exception as exc:
        return _error_envelope(
            block_id, action, f"{type(exc).__name__}: {exc}"
        )
    if isinstance(result, dict):
        status = str(result.get("status") or "").lower()
        failed = _failed_steps(result)
        if status in _FAILED_STATUSES or result.get("ok") is False or failed:
            refused = dict(result)
            refused["status"] = status if status in _FAILED_STATUSES else "error"
            refused.setdefault("block", block_id)
            refused["ok"] = False
            if failed and not refused.get("error"):
                refused["error"] = "; ".join(
                    "%s (%s): %s" % (
                        step.get("step_id") or "step",
                        step.get("block") or "?",
                        str(step.get("error") or step.get("status"))[:160],
                    )
                    for step in failed
                )
            return refused
    return result

"""Matter management for LexManage.

Written by the factory WRITER role (codewhale exec). Authored by the coding agent in the WRITER seat:
this module is the capability's real handler, not a contract template.

Domain: Centralized matter file: number, client, practice area, responsible attorney, stage, deadline and the matter brief.

Blocks (registry-verified, dispatched by keyword action):
  workflow         run              Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  database         insert           Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  document_engine  parse            Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  notification     send             Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.

Scope: READS caller input, STORAGE_PATH and the vendored Store blocks.
WRITES this capability's own alembic entity through store.save(ENTITY, ...)
and the local storage tree. NEVER performs network I/O, never writes
another tenant's rows, never persists to a table alembic 0001 did not
create.
"""

from __future__ import annotations

import json
from typing import Any, Dict

from app.dispatch import execute

CAPABILITY_ID = "matter_management"
ENTITY = 'matter_management'
BLOCK_IDS = ['workflow', 'database', 'document_engine', 'notification']
#: Each block's declared default action (from its block.json).
#: Blocks are action-dispatched; calling one with no action answers
#: 'Unknown action'.
BLOCK_DEFAULT_ACTIONS = {'workflow': 'run', 'database': 'insert', 'document_engine': 'parse', 'notification': 'send'}
#: This capability's own domain columns, declared so the kernel does
#: not strip a domain field that shares a trust-scope name.
CAPABILITY_FIELDS = ['reference', 'status', 'matter_number', 'matter_title', 'client_name', 'client_email', 'practice_area', 'responsible_attorney', 'matter_stage', 'priority', 'opened_date', 'deadline_date', 'billing_type', 'document_path']
_INSIGHT_KEY = 'matter_state'

REQUIRED_FIELDS = ['reference', 'status', 'matter_number', 'matter_title', 'client_name']

def _text(payload: Dict[str, Any], name: str) -> str:
    value = (payload or {}).get(name)
    return value.strip() if isinstance(value, str) else ("" if value is None else str(value))


def _int(payload: Dict[str, Any], name: str, default: int = 0) -> int:
    value = (payload or {}).get(name)
    if isinstance(value, bool):
        return default
    if isinstance(value, int):
        return value
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return default


def _float(payload: Dict[str, Any], name: str, default: float = 0.0) -> float:
    value = (payload or {}).get(name)
    if isinstance(value, bool):
        return default
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value))
    except (TypeError, ValueError):
        return default


def _email(payload: Dict[str, Any], name: str) -> str:
    value = _text(payload, name)
    return value if "@" in value else ""


def _record(payload: Dict[str, Any]) -> Dict[str, Any]:
    """The capability's own columns only: nothing block-specific leaks out."""
    data = payload if isinstance(payload, dict) else {}
    return {key: data[key] for key in CAPABILITY_FIELDS if key in data}

def _matter_brief(payload: Dict[str, Any]) -> str:
    """The matter brief every reviewer reads: who, what, when, how urgent."""
    parts = [
        "Matter " + (_text(payload, "matter_number") or "unreferenced"),
        "title: " + (_text(payload, "matter_title") or "untitled matter"),
        "client: " + (_text(payload, "client_name") or "unnamed client"),
        "practice area: " + (_text(payload, "practice_area") or "unassigned"),
        "responsible attorney: " + (_text(payload, "responsible_attorney") or "unassigned"),
        "stage: " + (_text(payload, "matter_stage") or "intake"),
        "opened: " + (_text(payload, "opened_date") or "undated"),
        "deadline: " + (_text(payload, "deadline_date") or "none recorded"),
        "billing: " + (_text(payload, "billing_type") or "hourly"),
    ]
    return "; ".join(parts)


def _deadline_state(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Deadline pressure as the firm records it (no clock, no guessing)."""
    deadline = _text(payload, "deadline_date")
    opened = _text(payload, "opened_date")
    stage = _text(payload, "matter_stage") or "intake"
    return {
        "deadline_date": deadline or None,
        "opened_date": opened or None,
        "matter_stage": stage,
        "deadline_recorded": bool(deadline),
        "matter_number": _text(payload, "matter_number"),
    }


def _block_input(block_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    """The object each bound block is handed, built from the matter record."""
    reference = _text(payload, "reference") or "unreferenced"
    number = _text(payload, "matter_number") or reference
    title = _text(payload, "matter_title") or "untitled matter"
    client = _text(payload, "client_name") or "unnamed client"
    attorney = _text(payload, "responsible_attorney") or "unassigned attorney"
    brief = _matter_brief(payload)
    if block_id == "database":
        return {
            "table": ENTITY,
            "values": {key: str(value) for key, value in _record(payload).items()},
        }
    if block_id == "document_engine":
        # The matter brief is the document this capability actually holds; a
        # caller-supplied document_path wins when the file exists on disk.
        return {
            "filename": number + ".txt",
            "content": brief,
            "input": {"reference": reference, "matter_title": title},
            "document_path": _text(payload, "document_path") or None,
        }
    if block_id == "notification":
        return {
            "channel": "email",
            "to": _email(payload, "client_email") or "matters@example.com",
            "subject": "Matter " + number + " opened: " + title,
            "message": brief,
            "block": CAPABILITY_ID,
            "tool": "notification",
        }
    if block_id == "workflow":
        # Every child is prepared: block, action, params.action and a real
        # input. The Store workflow reads the child's operation from params.
        return {
            "steps": [
                {
                    "block": "document_engine",
                    "action": "parse",
                    "params": {"action": "parse"},
                    "input": _block_input("document_engine", payload),
                },
                {
                    "block": "database",
                    "action": "insert",
                    "params": {"action": "insert"},
                    "input": _block_input("database", payload),
                },
                {
                    "block": "notification",
                    "action": "send",
                    "params": {"action": "send"},
                    "input": _block_input("notification", payload),
                },
            ],
            "result": {
                "reference": reference,
                "matter_number": number,
                "matter_title": title,
                "client_name": client,
                "responsible_attorney": attorney,
                "summary": brief,
            },
        }
    return dict(payload)


def _insight(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Matter state the firm reads back off the record."""
    return _deadline_state(payload)

def _normalise_matter(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Matter normalisation: the file always has a number, a title and a stage."""
    data = dict(payload) if isinstance(payload, dict) else {}
    reference = _text(data, "reference") or "unreferenced"
    data["reference"] = reference
    data["matter_number"] = _text(data, "matter_number") or reference
    data["matter_title"] = _text(data, "matter_title") or ("Matter " + reference)
    data["matter_stage"] = (_text(data, "matter_stage") or "intake").lower()
    data["priority"] = (_text(data, "priority") or "normal").lower()
    return data

def _persist_record(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Factory-grounded one-record persist. PRODUCT re-reads this entity.

    Store is imported here, not at module load: isolated contract probes
    exec this file against the factory ``app`` package (no product
    ``app.store``). A generated workspace still has ``app/store.py``.
    """
    record = dict(payload) if isinstance(payload, dict) else {}
    try:
        from app import store as _store
    except ImportError:
        return record
    return _store.save(ENTITY, record)


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    from app.offline_blocks import install_offline_block_adapters
    from app.paths import ensure_runtime_paths

    ensure_runtime_paths()
    payload = _normalise_matter(payload)

    # Sealed-vendor repair path: adopts an offline sink only for a Store
    # runtime module that cannot be imported at all (app/offline_blocks.py).
    install_offline_block_adapters()
    import app.dispatch as _dispatch
    try:
        from app.block_inputs import prepare_block_input as _prepare_block_input
    except ImportError:  # pragma: no cover - unit stubs without the module
        def _prepare_block_input(block_id, data, **_kw):
